def countDiffPairs(nums, k):
    n = len(nums)
    count = 0
    j = 0
    for i in range(n):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        if j < i + 1:
            j = i + 1
        while j < n and nums[j] - nums[i] < k:
            j += 1
        if j < n and nums[j] - nums[i] == k:
            count += 1
    return count
